size_t my_strlen(const char *s) {
    const char *p = s;
    while (*p) p++;
    return (size_t)(p - s);
}

char *my_strcpy(char *dest, const char *src) {
    char *d = dest;
    while ((*d++ = *src++))
        ;
    return dest;
}

char *my_strncpy(char *dest, const char *src, size_t n) {
    size_t i = 0;
    for (; i < n && src[i] != '\0'; i++) dest[i] = src[i];
    for (; i < n; i++) dest[i] = '\0';
    return dest;
}

char *my_strcat(char *dest, const char *src) {
    char *d = dest;
    while (*d) d++;
    while ((*d++ = *src++))
        ;
    return dest;
}

int my_strcmp(const char *s1, const char *s2) {
    while (*s1 && (*s1 == *s2)) { s1++; s2++; }
    return (int)(unsigned char)*s1 - (int)(unsigned char)*s2;
}

char *my_strstr(const char *haystack, const char *needle) {
    if (*needle == '\0') return (char *)haystack;
    for (; *haystack; haystack++) {
        const char *h = haystack, *n = needle;
        while (*h && *n && *h == *n) { h++; n++; }
        if (*n == '\0') return (char *)haystack;
    }
    return NULL;
}

char *my_strchr(const char *s, int c) {
    char target = (char)c;
    while (*s) {
        if (*s == target) return (char *)s;
        s++;
    }
    return (target == '\0') ? (char *)s : NULL;
}

int my_atoi(const char *str) {
    if (!str) return 0;
    const char *p = str;
    while (*p==' '||*p=='\t'||*p=='\n'||*p=='\r'||*p=='\v'||*p=='\f') p++;
    int sign = 1;
    if (*p=='+'||*p=='-') { if (*p=='-') sign = -1; p++; }
    long long acc = 0;
    while (*p>='0' && *p<='9') {
        acc = acc*10 + (*p-'0');
        if (sign==1 && acc > INT_MAX) return INT_MAX;
        if (sign==-1 && -acc < INT_MIN) return INT_MIN;
        p++;
    }
    return (int)(sign*acc);
}

char *my_itoa(int n, char *s, int base) {
    if (base < 2 || base > 16) { s[0] = '\0'; return s; }
    static const char digits[] = "0123456789abcdef";
    bool neg = false;
    unsigned int u;
    if (base == 10 && n < 0) { neg = true; u = (unsigned int)(-(long)n); }
    else u = (unsigned int)n;
    char tmp[35];
    int i = 0;
    if (u == 0) tmp[i++] = '0';
    while (u) { tmp[i++] = digits[u % (unsigned)base]; u /= (unsigned)base; }
    int j = 0;
    if (neg) s[j++] = '-';
    while (i > 0) s[j++] = tmp[--i];
    s[j] = '\0';
    return s;
}

void str_to_lower(char *s) {
    for (; *s; s++) if (*s >= 'A' && *s <= 'Z') *s = (char)(*s + ('a' - 'A'));
}
void str_to_upper(char *s) {
    for (; *s; s++) if (*s >= 'a' && *s <= 'z') *s = (char)(*s - ('a' - 'A'));
}

static void reverse_range(char *s, size_t lo, size_t hi) {
    while (lo < hi) { char t = s[lo]; s[lo] = s[hi]; s[hi] = t; lo++; hi--; }
}
void reverse_words(char *s) {
    size_t len = my_strlen(s);
    if (len == 0) return;
    reverse_range(s, 0, len - 1);
    size_t start = 0;
    for (size_t i = 0; i <= len; i++) {
        if (i == len || s[i] == ' ') {
            if (i > start) reverse_range(s, start, i - 1);
            start = i + 1;
        }
    }
}

void remove_duplicates(char *s) {
    bool seen[256] = { false };
    size_t w = 0;
    for (size_t r = 0; s[r]; r++) {
        unsigned char c = (unsigned char)s[r];
        if (!seen[c]) { seen[c] = true; s[w++] = s[r]; }
    }
    s[w] = '\0';
}

bool is_palindrome(const char *s) {
    size_t len = my_strlen(s);
    if (len == 0) return true;
    size_t i = 0, j = len - 1;
    while (i < j) {
        if (s[i] != s[j]) return false;
        i++; j--;
    }
    return true;
}

static bool in_delim(char c, const char *delim) {
    for (; *delim; delim++) if (c == *delim) return true;
    return false;
}
char *my_strtok(char *str, const char *delim) {
    static char *save = NULL;
    if (str) save = str;
    if (!save) return NULL;
    while (*save && in_delim(*save, delim)) save++;
    if (*save == '\0') { save = NULL; return NULL; }
    char *token = save;
    while (*save && !in_delim(*save, delim)) save++;
    if (*save) { *save = '\0'; save++; }
    return token;
}

static int emit_uint(char *out, unsigned int v, unsigned base, bool upper) {
    char tmp[32];
    const char *digs = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    int i = 0;
    if (v == 0) tmp[i++] = '0';
    while (v) { tmp[i++] = digs[v % base]; v /= base; }
    int n = 0;
    while (i > 0) out[n++] = tmp[--i];
    return n;
}
int my_sprintf(char *str, const char *format, ...) {
    va_list ap; va_start(ap, format);
    char *out = str;
    for (const char *f = format; *f; f++) {
        if (*f != '%') { *out++ = *f; continue; }
        f++;
        switch (*f) {
            case 'd': { int v = va_arg(ap, int); unsigned int mag;
                if (v < 0) { *out++ = '-'; mag = (unsigned int)(-(long)v); }
                else mag = (unsigned int)v;
                out += emit_uint(out, mag, 10, false); break; }
            case 'u': out += emit_uint(out, va_arg(ap, unsigned int), 10, false); break;
            case 'x': out += emit_uint(out, va_arg(ap, unsigned int), 16, false); break;
            case 'X': out += emit_uint(out, va_arg(ap, unsigned int), 16, true);  break;
            case 'c': *out++ = (char)va_arg(ap, int); break;
            case 's': { const char *sv = va_arg(ap, const char *);
                if (!sv) sv = "(null)";
                while (*sv) *out++ = *sv++; break; }
            case '%': *out++ = '%'; break;
            case '\0': f--; break;
            default: *out++ = '%'; *out++ = *f; break;
        }
    }
    *out = '\0';
    va_end(ap);
    return (int)(out - str);
}
